import pandas as pd

def find_all_matches(teams: pd.DataFrame) -> pd.DataFrame:
    df = teams.merge(teams, how='cross', suffixes=('_home', '_away'))
    df = df[df['team_name_home'] != df['team_name_away']]
    return df.rename(columns={'team_name_home': 'home_team', 'team_name_away': 'away_team'})
